detected=set()
for _,r in raw.iterrows():
    for w in range(1,comp[r.season]+1):
        for j in range(1,5):
            v=r[f'week{w}_judge{j}_score']
            if v=='N/A' or float(v)==0: continue
            x=float(v)
            if abs(x/0.5 - round(x/0.5))>1e-6:
                detected.add((r.season,w)); break
print('weeks caught by averaging rule:', sorted(detected))
allw = sorted(detected | {(9,1),(9,6),(10,6),(11,6),(12,9),(13,9),(14,6),(15,7),(16,7),(17,6),(19,8),(20,7),(21,8),(21,10),(23,8),(24,7),(26,3),(28,8),(30,7),(30,8),(31,5),(31,8),(32,6),(32,8),(32,9),(33,6),(34,7),(34,9)})
print('total detected multi-dance season-weeks:', len(allw))
mult={}
for _,r in raw.iterrows():
    for w in [w for (s2,w) in allw if s2==r.season]:
        pos=[float(r[f'week{w}_judge{j}_score']) for j in range(1,5) if r[f'week{w}_judge{j}_score']!='N/A' and float(r[f'week{w}_judge{j}_score'])>0]
        if pos: mult[(r.season,w,r.celebrity_name)]=(round(sum(pos),4), max(pos))
byweek=collections.defaultdict(list)
for (s,w,c),(tot,mx) in mult.items(): byweek[(s,w)].append((tot,mx,c))
for key in sorted(byweek):
    ts=[t for t,_,_ in byweek[key]]
